page=f'''<!doctype html><html lang="ru"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Восемь направлений цифровых технологий: устройство, применение, ограничения и перспективы. Иллюстрированный атлас библиотеки Переплёт."><title>Атлас современных цифровых технологий · Переплёт</title><link rel="stylesheet" href="/reading-atlas.css"><link rel="stylesheet" href="/digital-atlas.css"><script type="module" src="/digital-atlas.js"></script></head><body><a class="skip-link" href="#directions">К направлениям</a><header class="atlas-header"><a class="wordmark" href="/index.html#catalog">Переплёт<span>КНИГИ · МЫСЛЬ · ТЕХНОЛОГИИ</span></a><nav aria-label="Атласы">{nav}</nav><a class="back-link" href="/index.html#digital-books">К книгам раздела ↗</a></header><main>
<section class="digital-hero" aria-labelledby="digital-title"><div><p class="eyebrow">ПЕРЕПЛЁТ / КАРТА ЦИФРОВОГО МИРА</p><h1 id="digital-title">Атлас современных<br><em>цифровых технологий</em></h1><p class="hero-deck">От измерения к действию.<br>От инфраструктуры к человеку.</p><p class="prose">Датчик создаёт запись, сеть передаёт её, облако хранит и обрабатывает. Модель помогает увидеть закономерность, а интерфейс превращает результат в понятное действие. Исследуйте восемь направлений и связи, из которых складываются современные цифровые системы.</p><div class="hero-index"><span><b>08</b>направлений</span><span><b>01</b>связанная система</span><span><b>∞</b>поводов для изучения</span></div></div><figure class="hero-figure"><img src="/covers/digital-atlas/constellation.svg" width="600" height="350" alt="Карта восьми направлений вокруг человека: данные, AI, облако, сети, реестры, безопасность, квантовые технологии и UX"><figcaption>Схема связей: технологии приобретают смысл в задачах человека.</figcaption></figure></section>
<nav class="chapter-nav" aria-label="По атласу"><a href="#directions">Восемь направлений</a><a href="#connections">Как они работают вместе</a><a href="#cloud-lab">Кто за что отвечает в облаке</a><a href="#reading-route">С чего начать</a></nav>
<section id="directions" aria-labelledby="directions-title"><div class="section-heading"><p class="eyebrow">КАРТА / ВЫБЕРИТЕ НАПРАВЛЕНИЕ</p><h2 id="directions-title">Восемь способов понять<br>цифровую среду.</h2><p class="prose">Здесь нет рейтинга важности. Данные, инфраструктура, вычисление и пользовательский опыт решают разные задачи и дополняют друг друга. Откройте направление, чтобы увидеть устройство технологии, её применение и границы.</p></div><div class="direction-grid">'''
for t in topics:
 page+=f'''<a class="direction-card" href="#topic-{t['id']}"><img src="/covers/digital-atlas/{t['id']}.svg" width="600" height="350" alt="" loading="lazy"><span class="direction-number">{t['kicker'].split(' / ')[0]}</span><h3>{e(t['name'])}</h3><p>{e(t['deck'])}</p><span class="read-direction">Исследовать направление ↗</span></a>'''
page+='''</div></section><section id="connections" class="connections" aria-labelledby="connections-title"><div class="section-heading"><p class="eyebrow">СВЯЗИ / ОДНА ЗАДАЧА, НЕСКОЛЬКО ТЕХНОЛОГИЙ</p><h2 id="connections-title">Как устроена цифровая услуга.</h2><p class="prose">Рассмотрим учебные сценарии. Выберите задачу: схема покажет возможные роли технологий. Это варианты архитектуры, а не описание внутреннего устройства конкретного сервиса.</p></div><div id="scenario-controls" hidden><label for="scenario">Выберите задачу</label><select id="scenario"><option value="library">Цифровая библиотека</option><option value="industry">Производство и датчики</option><option value="research">Исследовательская лаборатория</option></select></div><div id="scenario-steps" class="scenario-steps"><article><span>01</span><h3>Сеть</h3><p>Читатель отправляет запрос с телефона.</p></article><article><span>02</span><h3>Облако и данные</h3><p>Приложение находит запись книги и передаёт документ.</p></article><article><span>03</span><h3>Безопасность и UX</h3><p>Система проверяет доступ, а интерфейс помогает продолжить чтение.</p></article></div><p id="scenario-note" class="scenario-note prose">Для обычного каталога не обязательны блокчейн и квантовый процессор. AI может помогать поиску, если его полезность проверена.</p></section>'''
for t in topics:
 page+=f'''<article id="topic-{t['id']}" class="topic-chapter" aria-labelledby="title-{t['id']}"><header class="topic-heading"><div><p class="eyebrow">{e(t['kicker'])}</p><h2 id="title-{t['id']}">{e(t['name'])}</h2><p class="topic-deck">{e(t['deck'])}</p></div><figure><img src="/covers/digital-atlas/{t['id']}.svg" width="600" height="350" loading="lazy" alt="Условная иллюстрация направления {e(t['name'])}"><figcaption>Авторская иллюстрация / {e(t['name'])}</figcaption></figure></header><div class="chapter-layout"><aside class="concepts"><h3>Понятия на полях</h3><dl>'''
 for term in t['terms']:page+=f'<dt>{e(term["term"])}</dt><dd>{e(term["text"])}</dd>'
 page+='</dl><a href="#directions">↑ К карте направлений</a></aside><div class="chapter-body">'
 for b in t['body']:page+=f'<section><h3>{e(b["title"])}</h3><p>{e(b["text"])}</p></section>'
 page+=f'''<aside class="case-study"><span class="eyebrow">ТЕХНОЛОГИЯ В ДЕЛЕ</span><p>{e(t['case'])}</p></aside><div class="boundaries"><section><h3>Ограничения и риски</h3><p>{e(t['limits'])}</p></section><section><h3>Горизонт развития</h3><p>{e(t['future'])}</p></section></div><aside class="practice"><h3>Вопрос для размышления</h3><p>{e(t['practice'])}</p></aside>'''
 if t['id']=='ai':
  page+='<nav class="ai-bridges" aria-label="Подробнее об искусственном интеллекте">'
  for name,url in [('Атлас AI','ai-atlas'),('Архитекторы AI','ai-architects'),('История AI','ai-history'),('Модели AI: что выбрать','ai-models'),('AI в России','ai-russia')]:page+=f'<a href="/{url}.html">{name} ↗</a>'
  page+='</nav>'
 page+='<details class="topic-sources"><summary>Первоисточники и дальнейшее чтение</summary><ul>'
 for source in t['sources']:page+=f'<li><a href="{e(source["url"])}" target="_blank" rel="noopener noreferrer">{e(source["label"])} ↗</a></li>'
 page+='</ul></details><nav class="related" aria-label="Связанные направления"><span>Связано с:</span>'
 for id in t['related']:
  other=next(x for x in topics if x['id']==id);page+=f'<a href="#topic-{id}">{e(other["name"])}</a>'
 page+='</nav></div></div></article>'
page+='''<section id="cloud-lab" class="cloud-lab" aria-labelledby="cloud-lab-title"><div class="section-heading"><p class="eyebrow">ПРАКТИКУМ / РАЗДЕЛЁННАЯ ОТВЕТСТВЕННОСТЬ</p><h2 id="cloud-lab-title">Что меняется при выборе облака?</h2><p class="prose">Сравните три типовые модели. Таблица показывает обобщённые границы управления, а не обязательства конкретного провайдера. Политика доступа, данные и выбор допустимого использования требуют внимания заказчика в любой модели.</p></div><fieldset id="cloud-model-controls" hidden><legend>Модель сервиса</legend><label><input type="radio" name="cloud-model" value="iaas" checked> IaaS</label><label><input type="radio" name="cloud-model" value="paas"> PaaS</label><label><input type="radio" name="cloud-model" value="saas"> SaaS</label></fieldset><div class="table-scroll" tabindex="0" role="region" aria-label="Таблица ответственности в облаке"><table><caption id="cloud-caption">IaaS: инфраструктура как сервис</caption><thead><tr><th scope="col">Область</th><th scope="col">Кто управляет в типовом случае</th></tr></thead><tbody id="cloud-rows"><tr><th scope="row">Физическое оборудование</th><td>Провайдер</td></tr><tr><th scope="row">Гостевая ОС</th><td>Заказчик</td></tr><tr><th scope="row">Платформа и приложение</th><td>Заказчик</td></tr><tr><th scope="row">Данные и права пользователей</th><td>Заказчик настраивает; обязанности согласуются с провайдером</td></tr></tbody></table></div><p id="cloud-note" class="prose" role="status" aria-live="polite">IaaS даёт больше контроля над ОС и приложением, но сохраняет больше эксплуатационной работы у заказчика.</p></section>
<section id="reading-route" class="reading-route" aria-labelledby="route-title"><div class="section-heading"><p class="eyebrow">МАРШРУТ / ОТ ПОНИМАНИЯ К ПРАКТИКЕ</p><h2 id="route-title">С чего начать изучение.</h2></div><div class="route-grid"><article><span>01 / ЧИТАТЕЛЮ</span><h3>Понять повседневную среду</h3><p>Начните с интернета и пользовательского опыта. Затем разберите, где хранятся данные и как защищаются ваши учётные записи.</p><a href="#topic-network">Интернет и 5G ↗</a></article><article><span>02 / РАЗРАБОТЧИКУ</span><h3>Собрать работающую систему</h3><p>Свяжите данные, облачную платформу и безопасность. Проверьте весь путь пользователя, включая ошибку, слабую связь и восстановление.</p><a href="/programming-atlas.html">Атлас языков программирования ↗</a></article><article><span>03 / РУКОВОДИТЕЛЮ ПРОЕКТА</span><h3>Оценить пользу и издержки</h3><p>Определите задачу, владельца результата и критерии успеха. Сравните простое решение с более сложным и проверьте, какая технология действительно необходима.</p><a href="#connections">Разобрать связи ↗</a></article></div><p class="closing prose">Хороший цифровой проект начинается с точного вопроса. Что должно измениться для человека, какие данные это подтвердят и кто отвечает за результат? Книги позволяют выйти за пределы короткого обзора и разобраться в каждом направлении глубже.</p><a class="books-link" href="/index.html#digital-books">К книгам о современных цифровых технологиях ↗</a></section><details class="editorial-method"><summary>О карте и источниках</summary><p>Восемь направлений образуют тематическую карту, а не исчерпывающую классификацию всех цифровых технологий. Основные понятия опираются на открытые материалы NIST, IETF, ITU, W3C, документацию разработчиков и исследовательских организаций. Ссылки приведены в каждом направлении. Примеры библиотеки, производства и лаборатории являются учебными, а перспективы описывают направления развития без обещаний сроков.</p><p>Редакционная дата: 31 октября 2026 года. Иллюстрации и схемы созданы для атласа; они не являются фотографиями оборудования или результатами измерений.</p></details></main><footer>ПЕРЕПЛЁТ · АТЛАС СОВРЕМЕННЫХ ЦИФРОВЫХ ТЕХНОЛОГИЙ<br>© 2026 Анцибор А.В.</footer></body></html>'''
(s/'digital-atlas.html').write_text(page)
